   },\n        {\n          \"label\": \"Hepatitis Testing\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"label\": \"Tested For Hepatitis B\",\n              \"type\": \"obs\",\n              \"id\": \"testedForHepatitisB\",\n              \"questionOptions\": {\n                \"concept\": \"da43c6af-312b-45ca-b132-07903437ff76\",\n                \"rendering\": \"select\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  },\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  }\n                ]\n              }\n            },\n            {\n              \"label\": \"Hepatitis B Test Result:\",\n              \"type\": \"obs\",\n              \"id\": \"hepatitisBTestResult\",\n              \"questionOptions\": {\n                \"concept\": \"159430AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"rendering\": \"select\",\n                \"answers\": [\n                  {\n                    \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Positive\"\n                  },\n                  {\n                    \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Negative\"\n                  },\n                  {\n                    \"concept\": \"730aad56-b755-4256-a832-4c2d85e4543a\",\n                    \"label\": \"Positive and on treatment\"\n                  }\n                ]\n              },\n              \"hide\": {\n                \"hideWhenExpression\": \"testedForHepatitisB !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n              }\n            },\n            {\n              \"label\": \"Was Patient Referred?\",\n              \"type\": \"obs\",\n              \"id\": \"hepatitisBReferred\",\n              \"questionOptions\": {\n                \"concept\": \"e6803842-1ad4-4edb-b98a-6ffc6a86791d\",\n                \"rendering\": \"select\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  },\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  }\n                ]\n              },\n              \"hide\": {\n                \"hideWhenExpression\": \"hepatitisBTestResult !== \'703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n              }\n            },\n            {\n              \"label\": \"Facility Refered To\",\n              \"type\": \"obs\",\n              \"id\": \"hepatitisBFacilityReferred\",\n              \"questionOptions\": {\n                \"concept\": \"1372f7f5-f0f1-477d-9e38-eecd59f9024d\",\n                \"rendering\": \"text\"\n              },\n              \"hide\": {\n                \"hideWhenExpression\": \"hepatitisBReferred !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n              }\n            },\n            {\n              \"label\": \"Tested For Hepatitis C\",\n              \"type\": \"obs\",\n              \"id\": \"testedForHepatitisC\",\n              \"questionOptions\": {\n                \"concept\": \"6df3f28d-93fd-4e7c-86ed-9f0568c7bb88\",\n                \"rendering\": \"select\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  },\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  }\n                ]\n              }\n            },\n            {\n              \"label\": \"Hepatitis C Test Result:\",\n              \"type\": \"obs\",\n              \"id\": \"hepatitisCTestResult\",\n              \"questionOptions\": {\n                \"concept\": \"161471AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"rendering\": \"select\",\n                \"answers\": [\n                  {\n                    \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Positive\"\n                  },\n                  {\n                    \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Negative\"\n                  },\n                  {\n                    \"concept\": \"730aad56-b755-4256-a832-4c2d85e4543a\",\n                    \"label\": \"Positive and on treatment\"\n                  }\n                ]\n              },\n              \"hide\": {\n                \"hideWhenExpression\": \"testedForHepatitisC !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n              }\n            },\n            {\n              \"label\": \"Was Patient Referred?\",\n              \"type\": \"obs\",\n              \"id\": \"hepatitisCReferred\",\n              \"questionOptions\": {\n                \"concept\": \"e6803842-1ad4-4edb-b98a-6ffc6a86791d\",\n                \"rendering\": \"select\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  },\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  }\n                ]\n              },\n              \"hide\": {\n                \"hideWhenExpression\": \"hepatitisCTestResult !== \'703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n              }\n            },\n            {\n              \"label\": \"Facility Refered To\",\n              \"type\": \"obs\",\n              \"id\": \"hepatitisCFacilityReferred\",\n              \"questionOptions\": {\n                \"concept\": \"1372f7f5-f0f1-477d-9e38-eecd59f9024d\",\n                \"rendering\": \"text\"\n              },\n              \"hide\": {\n                \"hideWhenExpression\": \"hepatitisCReferred !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"Signature\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"label\": \"Provider Name\",\n              \"type\": \"encounterProvider\",\n              \"required\": true,\n              \"id\": \"providerName\",\n              \"questionOptions\": {\n                \"rendering\": \"ui-select-extended\"\n              },\n              \"validators\": []\n            },\n            {\n              \"label\": \"Visit Date\",\n              \"type\": \"encounterDatetime\",\n              \"required\": true,\n              \"id\": \"visitDate\",\n              \"datePickerFormat\": \"calendar\",\n              \"questionOptions\": {\n                \"rendering\": \"date\"\n              },\n              \"validators\": []\n            },\n            {\n              \"label\": \"Facility Name\",\n              \"type\": \"encounterLocation\",\n              \"required\": true,\n              \"id\": \"facilityName\",\n              \"questionOptions\": {\n                \"rendering\": \"ui-select-extended\"\n              },\n              \"validators\": []\n            }\n          ]\n        }\n      ]\n    }\n  ],\n  \"encounterType\": \"c6f26a9a-5a8c-493a-a5a7-57bd2c81628d\"\n}');
