(64, 'dcde8b9f-3166-11f0-b8e6-0a0027000011', '{\n  \"name\": \"Client Tracking and Termination.\",\n  \"description\": \"Json form for client tracking and termination\",\n  \"version\": \"2025\",\n  \"published\": false,\n  \"retired\": false,\n  \"processor\": \"EncounterFormProcessor\",\n  \"encounter\": \"Client Tracking and Termination\",\n  \"referencedForms\": [],\n  \"uuid\": \"5fbc99be-9aeb-4f94-85b0-b2fae88a0ced\",\n  \"pages\": [\n    {\n      \"label\": \"Client Tracking And Discontinuation Form\",\n      \"sections\": [\n        {\n          \"label\": \"Client Verification\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"label\": \"Client Verified?\",\n              \"type\": \"obs\",\n              \"id\": \"clientVerification\",\n              \"questionOptions\": {\n                \"concept\": \"ed586055-dedd-42d3-b87b-2a06715459bd\",\n                \"rendering\": \"select\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  },\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  }\n                ]\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \"Indication for Client Verification: (Reason /Trigger/Indication for Client Verification, you can select multiple triggers)\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"label\": \"Reasons for Client Verification\",\n              \"type\": \"obs\",\n              \"id\": \"verificationReasons\",\n              \"inlineMultiCheckbox\": true,\n              \"questionOptions\": {\n                \"concept\": \"ed586055-dedd-42d3-b87b-2a06715459bd\",\n                \"rendering\": \"checkbox\",\n                \"answers\": [\n    