(75, 'dce6b32b-3166-11f0-b8e6-0a0027000011', '{\r\n    \"name\": \"Risk Assessment Pediatric\",\r\n    \"description\": null,\r\n    \"version\": \"2018\",\r\n    \"published\": false,\r\n    \"retired\": false,\r\n    \"processor\": \"EncounterFormProcessor\",\r\n    \"encounter\": \"Risk Stratification Pediatrics\",\r\n    \"referencedForms\": [],\r\n    \"uuid\": \"a3524d1a-40cd-4bcd-b21c-82fbb0eab3db\",\r\n    \"pages\": [\r\n      {\r\n        \"label\": \"Risk Assessment Pediatrics\",\r\n        \"sections\": [\r\n          {\r\n            \"label\": \"INSTRUCTIONS\",\r\n            \"isExpanded\": true,\r\n            \"questions\": [\r\n              {\r\n                \"id\": \"instructions\",\r\n                \"value\": [\r\n                  \"#### **---------------- Risk Stratification ----------------** ####\",\r\n                  \"I\'m going to ask you some questions to better understand your HIV risk. These can be very personal questions and may be hard to answer. In order to accurately understand your risk for HIV, I need to ask these questions and I need you to answer them as honestly as possible. If you need a moment to think before answering that is fine. Whatever we discuss will remain confidential\"\r\n                ],\r\n                \"questionOptions\": {\r\n                  \"rendering\": \"markdown\"\r\n                }\r\n              }\r\n            ]\r\n          },\r\n          {\r\n            \"label\": \"Risk Stratification\",\r\n            \"isExpanded\": true,\r\n            \"questions\": [\r\n              {\r\n                \"label\": \"Is The Child/adolescent\'s Biological Mother Hiv-positive Or Are One (1) Or More Of The Child/adolescent?s Biological Parents Deceased Due To An Unknown Or Undisclosed Illness?\",\r\n                \"type\": \"obs\",\r\n                \"id\": \"child_biological_parent_hiv_positive_or_deseased\",\r\n                \"questionOptions\": {\r\n                  \"concept\": \"cacc7904-58f6-4c71-8525-2e663021a73b\",\r\n                  \"rendering\": \"select\",\r\n                  \"answers\": [\r\n                    {\r\n                      \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                      \"label\": \"No\"\r\n                    },\r\n                    {\r\n                      \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                      \"label\": \"Yes\"\r\n                    }\r\n                  ]\r\n                }\r\n              },\r\n              {\r\n                \"label\": \"Has The Child/adolescent Ever Been Tested For Hiv?\",\r\n                \"type\": \"obs\",\r\n                \"id\": \"child_ever_tested_for_hiv\",\r\n                \"questionOptions\": {\r\n                  \"concept\": \"ecb19ce0-4b7f-4092-a168-69030f37f326\",\r\n                  \"rendering\": \"select\",\r\n                  \"answers\": [\r\n                    {\r\n                      \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                      \"label\": \"No\"\r\n                    },\r\n                    {\r\n                      \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                      \"label\": \"Yes\"\r\n                    }\r\n                  ]\r\n                }\r\n              },\r\n              {\r\n                \"label\": \"Has The Child/adolescent Had Repeated/recurring Skin Problems, Rashes And/or Blisters In The Last Six Months?\",\r\n                \"type\": \"obs\",\r\n                \"id\": \"child_had_recurring_skin_problem\",\r\n                \"questionOptions\": {\r\n                  \"concept\": \"b58a1127-1862-438e-9069-ad3e79955cfa\",\r\n                  \"rendering\": \"select\",\r\n                  \"answers\": [\r\n                    {\r\n                      \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                      \"label\": \"No\"\r\n                    },\r\n       