(14, '7b6d6d61-31b6-11f0-9444-00e04c364c8c', '{\"name\":\"Delivery Register\",\"uuid\":\"3a9299e5-25b6-4489-9878-0cdfba06fba1\",\"processor\":\"EncounterFormProcessor\",\"version\":\"1.1\",\"published\":true,\"retired\":false,\"description\":\"Delivery Register - CCFN\",\"pages\":[{\"label\":\"Delivery Information\",\"sections\":[{\"label\":\"Delivery Information\",\"questions\":[{\"label\":\"Date of delivery\",\"type\":\"encounterDatetime\",\"required\":true,\"id\":\"dateOfDelivery\",\"datePickerFormat\":\"both\",\"questionOptions\":{\"rendering\":\"date\"},\"validators\":[{\"type\":\"date\",\"allowFutureDates\":\"false\"}]},{\"label\":\"Time of HIV diagnosis:\",\"type\":\"obs\",\"id\":\"timeofHIVdiagnosis\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"164851AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"c67dc265-75d5-493a-b142-8bf7be6d7fa7\",\"label\":\"ANC\"},{\"concept\":\"77e710b5-ec47-4b0c-8e0b-de5837a48aae\",\"label\":\"L&D Booked\"},{\"concept\":\"820b93f4-5caa-4acc-8167-a479ac68ee4e\",\"label\":\"L&D Unbooked\"},{\"concept\":\"5a6f8782-f3f0-46a9-b224-90770f57807a\",\"label\":\"Previously known HIV+\"}]}},{\"label\":\"GA (wks) at birth\",\"id\":\"gestational_age\",\"questionOptions\":{\"rendering\":\"number\",\"concept\":\"1409AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"max\":\"50\",\"min\":\"1\",\"step\":1,\"disallowDecimals\":true},\"type\":\"obs\",\"validators\":[{\"type\":\"js_expression\",\"failsWhenExpression\":\"gestational_age && (gestational_age < 1 || gestational_age > 50 || gestational_age % 1 !== 0)\",\"message\":\"Gestational age must be a whole number between 1 and 50 weeks.\"}]},{\"label\":\"Hepatitis B Status\",\"type\":\"obs\",\"id\":\"hep_B_status\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"159430AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Positive\"},{\"concept\":\"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Negative\"}]}},{\"