(22, 'dce2f01f-3166-11f0-b8e6-0a0027000011', '{\"name\":\"LGA-Health Facility TB Central Register Form\",\"description\":\"Comprehensive TB patient registration and tracking form with enhanced validations - CCFN\",\"version\":\"2.0\",\"published\":true,\"retired\":false,\"processor\":\"EncounterFormProcessor\",\"encounter\":\"LGA-Health Facility TB Central Register Form\",\"referencedForms\":[],\"uuid\":\"6712afd4-8dba-47e3-ad19-79b8aafe9461\",\"encounterType\":\"664465bf-e18d-416c-b154-c595324ec4e7\",\"pages\":[{\"label\":\"TB Central Register\",\"sections\":[{\"label\":\"Patient Registration Details\",\"isExpanded\":true,\"questions\":[{\"label\":\"Date Registered\",\"type\":\"obs\",\"id\":\"date_tb_registered\",\"required\":true,\"questionInfo\":\"Date when patient was registered in TB program\",\"questionOptions\":{\"concept\":\"56586a04-8c92-4365-960c-4ccd31c941ee\",\"rendering\":\"date\",\"max\":\"today()\"},\"validators\":[{\"type\":\"required\",\"message\":\"Registration date is required\"},{\"type\":\"js_expression\",\"failsWhenExpression\":\"myValue && isDateBefore(today(), myValue)\",\"message\":\"Registration date cannot be in the future\"}]},{\"label\":\"Type Of Patient\",\"type\":\"obs\",\"id\":\"type_of_tb_patient\",\"required\":true,\"questionInfo\":\"Classification of patient based on treatment history\",\"questionOptions\":{\"concept\":\"d0b7c50f-bc23-47a0-a487-38783e05259f\",\"rendering\":\"select\",\"answers\":[{\"concept\":\"159878AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"New\"},{\"concept\":\"159875AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Relapse\"},{\"concept\":\"159873AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Treatment after default\"},{\"concept\":\"88def77a-96fd-42e4-a013-923ca73e806f\",\"label\":\"Treatment after LTFU\"},{\"concept\":\"29c3b9ac-1bca-42a5-8701-1227533ac79a\",\"label\":\"Transferred-In TB\"},{\"concept\":\"585be590-25eb-4411-b7a3-2a7176a6478d\",\"label\":\"Others previously treated\"},{\"concept\":\"5ed7f56e-bb0b-4e78-a0a1-8ffcfd5b7fbd\",\"label\":\"Unknown previous TB\"}]},\"validators\":[{\"type\":\"required\",\"message\":\"Patient type is required\"}]},{\"label\":\"LGA TB Number\",\"type\":\"obs\",\"id\":\"lga_tb_number\",\"required\":true,\"questionInfo\":\"Local Government Area TB identification number\",\"questionOptions\":{\"concept\":\"b7dfe666-7a00-42f8-bb7f-8f81f315488c\",\"rendering\":\"text\",\"maxLength\":\"20\"},\"validators\":[{\"type\":\"required\",\"message\":\"LGA TB Number is required\"}]},{\"label\":\"E-TB Manager Unique Number\",\"type\":\"obs\",\"id\":\"e_tb_manager_unique_number\",\"questionInfo\":\"Electronic TB Manager system unique identifier\",\"questionOptions\":{\"concept\":\"235a0434-f1c8-445c-b432-fdbc280ecbe3\",\"rendering\":\"text\",\"maxLength\":\"30\"}},{\"label\":\"Facility Where Patient Started Treatment\",\"type\":\"obs\",\"id\":\"facility_where_patient_started_treatment\",\"required\":{\"type\":\"conditionalRequired\",\"message\":\"Required for transferred patients\",\"referenceQuestionId\":\"type_of_tb_patient\",\"referenceQuestionAnswers\":[\"29c3b9ac-1bca-42a5-8701-1227533ac79a\"]},\"questionInfo\":\"Name of facility where treatment was initiated\",\"questionOptions\":{\"concept\":\"15e9261b-541d-45f8-9943-3861f33eb13f\",\"rendering\":\"text\",\"maxLength\":\"100\"}}]},{\"label\":\"Clinical Assessment\",\"isExpanded\":true,\"questions\":[{\"label\":\"Weight At The Start Of Treatment (kg)\",\"type\":\"obs\",\"id\":\"weight_at_the_start_of_treatment\",\"required\":true,\"questionInfo\":\"Patient\'s weight in kilograms at treatment initiation\",\"questionOptions\":{\"concept\":\"625dd627-d1cf-4b6d-bac8-9b946448dce0\",\"rendering\":\"text\",\"max\":\"200\",\"min\":\"1\",\"step\":\"1\"},\"validators\":[{\"type\":\"required\",\"message\":\"Weight is required\"},{\"type\":\"js_expression\",\"failsWhenExpression\":\"isNaN(myValue) || myValue === \'\'\",\"message\":\"Weight must be a number\"},{\"type\":\"js_expression\",\"failsWhenExpression\